"""External-evidence review; never calibrates a force to a desired magnitude."""
import json,hashlib,html
from pathlib import Path
import numpy as np
from jump_rig import ROOT

def main():
    out=ROOT/'results/jump_contact_visualization';source=ROOT/'results/contact_jump_scapula/600hz'
    foot=json.loads((out/'foot_force_balance.json').read_text());calf=json.loads((source/'calf_moment_audit.json').read_text());quality=json.loads((source/'motion_quality.json').read_text());motion=np.load(source/'motion.npz');t=np.load(source/'tensions.npz')
    a=foot['audits'][0];b=calf['audits'][0];resultant=float(np.linalg.norm(a['calf_force_vector_N']));W=90*9.80665
    refs=[dict(id='fukashiro1995',authors='Fukashiro et al.',year=1995,doi='10.1007/BF00635880',url='https://pubmed.ncbi.nlm.nih.gov/8565978/',measurement='Implanted buckle transducer around right Achilles tendon',n=1,CMJ_peak_N=1895,SJ_peak_N=2233,hopping_peak_N=3786,CMJ_height_cm=40,SJ_height_cm=33,hopping_height_cm=7,limitations='Single participant, different body/motion. Not a population upper bound. Do not count the similar 1993 report as an independent replication.'),
          dict(id='fukashiro1993',authors='Fukashiro et al.',year=1993,doi='10.1016/S0268-0033(05)80006-3',url='https://www.sciencedirect.com/science/article/pii/S0268003305800063',measurement='Implanted transducer versus ankle-moment-derived force',n=1,CMJ_peak_N=1896,SJ_peak_N=2234,hopping_peak_N=3787,finding='Moment-derived force overestimated direct force during early plantarflexion; maximum estimation error was relatively large.',limitations='Closely related historical report, not independent confirmation of the 1995 observations.'),
          dict(id='devaprakash2022',authors='Devaprakash et al.',year=2022,doi='10.1152/japplphysiol.00662.2021',url='https://doi.org/10.1152/japplphysiol.00662.2021',author_manuscript='https://research-repository.griffith.edu.au/server/api/core/bitstreams/89b69e60-51a9-4b02-8d5c-396cd0bc536f/content',measurement='Personalized EMG-informed model compared with digitized historical invasive measurements',n=16,mass_mean_kg=64.4,mass_SD_kg=8.4,CMJ_height_mean_cm=41.2,CMJ_height_SD_cm=8.2,CMJ_group_mean_curve_peak_approx_N=[2100,2200],peak_provenance='Visual reading of Figure 3; approximate peak of the group-mean curve, not mean individual peak or an upper reference limit.',CMJ_curve_R_squared=.86,CMJ_curve_RMSE_N=309,reported_peak_difference_vs_historical_direct_percent=14,limitations='Different cohort from the historical direct-force data. Curves digitized and time-normalized; not simultaneous invasive validation on the same 16 participants.'),
          dict(id='finni2000',authors='Finni et al.',year=2000,doi='10.1007/s004210000289',url='https://pubmed.ncbi.nlm.nih.gov/11138584/',measurement='Optic-fibre tendon force measurements',n=4,tasks='Submaximal bilateral force-plate jumps and unilateral sledge jumps',limitations='Relevant primary candidate. Exact numerical force curves were not extracted because repository full text could not be retrieved; excluded from quantitative comparison.')]
    current=dict(mass_kg=90,calf_scalar_sum_N=a['calf_scalar_tension_sum_N'],calf_whole_foot_force_resultant_N=resultant,calf_resultant_bodyweights=resultant/W,scalar_resultant_relative_difference=abs(a['calf_scalar_tension_sum_N']-resultant)/resultant,peak_time_s=a['time_s'],COM_vertical_speed_at_calf_peak_m_s=float(motion['velocity'][t['source_indices'][int(np.argmin(abs(t['times']-a['time_s'])))],2]),total_GRF_peak_N=quality['checks']['peak_total_vertical_GRF_N'],COM_airborne_rise_from_takeoff_cm=quality['checks']['COM_rise_after_takeoff_m']*100,ankle_reaction_at_calf_peak_N=a['proximal_reaction_magnitude_N'],effective_calf_arm_cm=b['force_weighted_calf_moment_arm_m']*100,external_ankle_lever_cm=b['effective_external_lever_m']*100)
    review=dict(status='external_validation_not_passed',reason='Relevant references exist, but current muscle and joint loads have not been validated against a matched experiment. Published CMJ force magnitudes do not currently justify accepting this model output.',current=current,references=refs,comparison=dict(reference_group_mean_peak_bodyweights_approx=[v/(64.4*9.80665) for v in [2100,2200]],normalization_note='Ratio of approximate mean-curve peak to mean bodyweight only. Not individual normalization, confidence interval, physiological ceiling, or a valid linear scaling law.',metric_note='Current calf insertion resultant is a triceps-surae loading proxy. It is closer to the tendon-force observable than a scalar muscle sum, but it is not a validated common-Achilles tendon output.',joint_force_note='No matched in-vivo ankle joint-reaction benchmark was established by these tendon studies.'),required_matched_benchmark=['Use experimental CMJ motion and GRF/COP for the same trial and stated subject mass.','Define a common Achilles tendon force output and distinguish it from total calf scalar tension and ankle reaction.','Replay experimental kinematics/external forces without retuning moment arms to force agreement.','Compare force-time phase, peak, impulse and normalized magnitudes; report uncertainty and measurement limitations.','Audit COP/foot geometry, ankle axis and muscle paths, passive reference floors and force-sharing sensitivity.'],source_motion_sha256=hashlib.sha256((source/'motion.npz').read_bytes()).hexdigest(),forces_modified=False)
    (out/'external_reference_review.json').write_text(json.dumps(review,indent=2))
    # Preserve the numerical status: this is a separate external-validity gate.
    validation=json.loads((out/'validation.json').read_text());validation['external_reference_validation']=dict(status=review['status'],report='reference_review.html',forces_modified=False);(out/'validation.json').write_text(json.dumps(validation,indent=2))
    content=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>External reference review</title><style>body{{max-width:1000px;margin:30px auto;padding:20px;background:#0d1726;color:#edf3fb;font:18px/1.65 system-ui}}a{{color:#8ce2d5}}strong{{color:#f0b74e}}table{{border-collapse:collapse}}td,th{{border:1px solid #465e76;padding:10px}}.scroll{{overflow:auto}}</style><a href="index.html">Viewer</a> · <a href="calf_audit.html">Mechanical audit</a><h1>External validity: not passed</h1><p><strong>Force and moment closure is necessary, but is not evidence that individual muscle forces or ideal-joint reactions are realistic.</strong> No force values have been capped, scaled to a paper or changed by this review.</p><h2>Relevant direct measurements</h2><p><a href="{refs[0]['url']}">Fukashiro et al. (1995)</a> measured right Achilles tendon force with an implanted buckle transducer in one adult: maximal squat jump 2,233 N, countermovement jump 1,895 N and hopping 3,786 N. Reported jump heights were 33, 40 and 7 cm, respectively. This single-subject result is not a population ceiling. Hopping is a different task from a bilateral CMJ.</p><p><a href="{refs[1]['url']}">The related 1993 direct-versus-inverse study</a> specifically warns of force overestimation during early plantarflexion. These closely related historical reports must not be counted as independent cohorts.</p><h2>A contemporary model comparison</h2><p><a href="{refs[2]['url']}">Devaprakash et al. (2022)</a> studied 16 trained runners (64.4 ± 8.4 kg; maximal CMJ height 41.2 ± 8.2 cm) with personalized anatomy and an EMG-informed model. Figure 3 shows a CMJ group-mean curve peak approximately 2.1–2.2 kN. This is a visual approximation, not a tabulated mean of individual peaks. The study reports CMJ curve R²=0.86 and RMSE=309 N versus digitized historical transducer data, with its peak about 14% higher. This was a cross-study comparison, not a simultaneous invasive measurement in the same runners.</p><p><a href="references/devaprakash2022.pdf">Inspected author manuscript</a>. Figure 3 is PDF page 27; subject/task conditions are pages 6–8. The journal's 2022 publication date, not the repository upload date, is used.</p><div class="scroll"><table><tr><th>Quantity</th><th>Published 2022 CMJ</th><th>Current diagnostic model</th></tr><tr><td>Subject mass</td><td>64.4 ± 8.4 kg, n=16</td><td>90 kg generic</td></tr><tr><td>Height descriptor</td><td>Maximal jump height 41.2 ± 8.2 cm</td><td>COM rise after takeoff {current['COM_airborne_rise_from_takeoff_cm']:.1f} cm; definition not yet matched</td></tr><tr><td>Force observable</td><td>Modeled free Achilles force</td><td>Calf scalar sum {current['calf_scalar_sum_N']:.0f} N; insertion resultant proxy {resultant:.0f} N</td></tr><tr><td>Bodyweight ratio</td><td>Approx. 3.3–3.5 using mean mass and mean-curve peak</td><td>{resultant/W:.2f}</td></tr></table></div><p><strong>This comparison does not validate the current approximately 5.1 kN result.</strong> It also cannot establish a universal 2 kN ceiling: mass, task, motion and measurement definitions differ. The current small-jump controller has not reproduced a matched experimental trial.</p><p>Its ankle reaction magnitude is {a['proximal_reaction_magnitude_N']:.0f} N at this calf peak. Achilles tendon papers do not validate that separate joint-reaction quantity.</p><h2>What to check next</h2><ol>{''.join('<li>'+html.escape(x)+'</li>' for x in review['required_matched_benchmark'])}</ol><p><a href="{refs[3]['url']}">Finni et al. (2000)</a> is a relevant independent optic-fibre study of four volunteers. Numerical curves were not recovered here and have not been assigned invented values.</p><p><a href="external_reference_review.json">Structured evidence and limits</a> · <a href="validation.json">Separate numerical checks</a></p></html>'''
    (out/'reference_review.html').write_text(content,encoding='utf-8')
    for name in ['method.html','calf_audit.html']:
        file=out/name;text=file.read_text(encoding='utf-8')
        if 'reference_review.html' not in text:
            text=text.replace('<h1>','<p><strong>External validity not passed.</strong> <a href="reference_review.html">Direct-measurement and contemporary model comparison</a>.</p><h1>',1)
            file.write_text(text,encoding='utf-8')
    print('EXTERNAL_REFERENCE_REVIEW',json.dumps(current),flush=True)

if __name__=='__main__':main()
